import{_ as t,c as a,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const n="/docs/screenshots/qptiff-slide.webp",u=JSON.parse('{"title":"Akoya QPTIFF Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Akoya PhenoCycler and Vectra QPTIFF slides in your browser: multiplex fluorescence with marker names. Free, nothing to install.","frontmatter":{"title":"Akoya QPTIFF Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Akoya PhenoCycler and Vectra QPTIFF slides in your browser: multiplex fluorescence with marker names. Free, nothing to install."},"headers":[],"relativePath":"guides/akoya-qptiff.md","filePath":"guides/akoya-qptiff.md"}'),i={name:"guides/akoya-qptiff.md"};function s(l,e,d,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="akoya-qptiff-slides-in-the-browser" tabindex="-1">Akoya QPTIFF Slides in the Browser <a class="header-anchor" href="#akoya-qptiff-slides-in-the-browser" aria-label="Permalink to &quot;Akoya QPTIFF Slides in the Browser&quot;">​</a></h1><p>Open the slides your Akoya PhenoCycler-Fusion or Vectra saves, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><p>Multiplex fluorescence opens with every channel, named and coloured as in the scan.</p><img width="1500" height="950" src="'+n+'" alt="A tissue microarray from a PhenoCycler-Fusion open in the viewer: nine cores in many colours, and the Channels tab listing 59 markers such as DAPI, CD123, Ki67 and CD3e, each with its colour and contrast" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens, several show a list. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide.</strong> Zoom from the whole slide down to single cells.</li><li><strong>Brightfield.</strong> H&amp;E and other stains open in colour.</li><li><strong>Multiplex fluorescence.</strong> Each channel opens with its marker name and colour from the scan, such as DAPI, CD3e or Pan-Cytokeratin. A scan of 59 markers opens with all 59, the first 10 turned on. Turn channels on and off, and set each one&#39;s contrast.</li><li><strong>A channel with no colour.</strong> Shown in white, with a note.</li><li><strong>Pixel size and magnification.</strong> Both come from the scan, so measurements read in µm and the zoom bar shows the objective. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>The thumbnail, overview and label pictures in the file are not shown.</p><h2 id="inform-component-exports" tabindex="-1">inForm Component Exports <a class="header-anchor" href="#inform-component-exports" aria-label="Permalink to &quot;inForm Component Exports&quot;">​</a></h2><p>inForm saves the unmixed result as a <code>.tif</code> file, one channel per component, such as Hematoxylin and Eosin. Drop it on the viewer like a slide.</p><p>It opens dark on white, so it reads like the stained slide it came from.</p><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>Another compression</td><td>This QPTIFF uses a compression the viewer cannot read yet.</td></tr><tr><td>Another pixel type</td><td>This QPTIFF has a pixel type the viewer cannot read yet.</td></tr><tr><td>Pages of different pixel types</td><td>The pages of this QPTIFF do not share one pixel type. The viewer cannot read it yet.</td></tr><tr><td>Several planes per channel</td><td>This QPTIFF holds more than one plane per channel. The viewer reads one plane per channel for now.</td></tr><tr><td>A resolution missing a channel</td><td>A resolution level of this QPTIFF lacks a channel. The viewer cannot read it yet.</td></tr><tr><td>Not a QPTIFF</td><td>This file is not an Akoya QPTIFF.</td></tr><tr><td>Damaged or cut short</td><td>This QPTIFF looks damaged or incomplete.</td></tr></tbody></table><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://zenodo.org/records/15825670" target="_blank" rel="noreferrer">Zenodo record 15825670</a> holds a 59-marker PhenoCycler-Fusion scan of a tissue microarray, CC BY 4.0. Download the zip, unpack it, and drop the <code>.qptiff</code> on the viewer.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>240508_VET_QCTMA2_A2_55p_Scan1.qptiff</code> from <a href="https://zenodo.org/records/15825670" target="_blank" rel="noreferrer">Zenodo record 15825670</a>, by Bryce Fukuda, Jocelyn Wright, Kimberly Smythe and Cecilia Yeung, raw data for the publication &quot;Graphical and Interactive Spatial Proteomics Image Analysis Workflow&quot;, CC BY 4.0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',28)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
